import { Pressable, View } from "react-native";
import { useSkeuo, useFeedback } from "./theme";
import { styles } from "./styles";
import type { OptionsProps } from "./types";
import { SkeuoText } from "./skeuo-text";
export function SkeuoRadioGroup({
  label,
  value,
  onValueChange,
  options,
}: OptionsProps) {
  const { colors } = useSkeuo();
  const feedback = useFeedback();
  return (
    <View
      accessibilityRole="radiogroup"
      accessibilityLabel={label}
      style={styles.stack}
    >
      {options.map((option) => (
        <Pressable
          key={option.value}
          accessibilityRole="radio"
          aria-checked={value === option.value}
          aria-disabled={!!option.disabled}
          accessibilityLabel={option.label}
          accessibilityState={{
            checked: value === option.value,
            disabled: !!option.disabled,
          }}
          disabled={option.disabled}
          onPress={() => {
            feedback();
            onValueChange(option.value);
          }}
          style={[
            styles.row,
            styles.touch,
            { opacity: option.disabled ? 0.45 : 1 },
          ]}
        >
          <View
            style={[
              styles.check,
              {
                borderRadius: 20,
                borderColor: colors.edge,
                backgroundColor: colors.well,
              },
            ]}
          >
            {value === option.value && (
              <View
                style={{
                  width: 12,
                  height: 12,
                  borderRadius: 6,
                  backgroundColor: colors.accent,
                }}
              />
            )}
          </View>
          <SkeuoText>{option.label}</SkeuoText>
        </Pressable>
      ))}
    </View>
  );
}

import React, { createContext, useContext } from "react";
import { useColorScheme } from "nativewind";
import * as Haptics from "expo-haptics";

export const themes = {
  light: {
    background: "#ffffff",
    surface: "#f5f5f2",
    raised: "#fafaf8",
    well: "#e9e9e5",
    edge: "#d1d1cb",
    base: "#d9d9d3",
    ink: "#202020",
    muted: "#686863",
    accent: "#365e50",
    accentInk: "#ffffff",
  },
  dark: {
    background: "#000000",
    surface: "#191919",
    raised: "#252525",
    well: "#111111",
    edge: "#3b3b39",
    base: "#080808",
    ink: "#efefeb",
    muted: "#aaaAA5",
    accent: "#9ab5a6",
    accentInk: "#14251c",
  },
};
type ThemeState = { colors: typeof themes.light; dark: boolean; haptics: boolean; onSound?: () => void };
const Context = createContext<ThemeState | null>(null);
export function SkeuoProvider({
  children,
  appearance = "system",
  haptics = false,
  onSound,
  colors: overrides,
}: {
  children: React.ReactNode;
  appearance?: "light" | "dark" | "system";
  haptics?: boolean;
  onSound?: () => void;
  colors?: Partial<typeof themes.light>;
}) {
  const { colorScheme: system } = useColorScheme();
  const dark = (appearance === "system" ? system : appearance) === "dark";
  return (
    <Context.Provider
      value={{
        colors: { ...(dark ? themes.dark : themes.light), ...overrides },
        dark,
        haptics,
        onSound,
      }}
    >
      {children}
    </Context.Provider>
  );
}
export function useSkeuo(): ThemeState {
  const context = useContext(Context);
  const { colorScheme } = useColorScheme();
  return context ?? { colors: colorScheme === "dark" ? themes.dark : themes.light, dark: colorScheme === "dark", haptics: false };
}
export function useFeedback() {
  const { haptics, onSound } = useSkeuo();
  return () => {
    onSound?.();
    if (haptics) void Haptics.selectionAsync().catch(() => {});
  };
}

import React from "react";
export type ButtonProps = {
  children: React.ReactNode;
  onPress: () => void;
  disabled?: boolean;
  variant?: "default" | "accent";
  accessibilityLabel?: string;
};
export type ToggleProps = {
  label: string;
  checked: boolean;
  onCheckedChange: (checked: boolean) => void;
  disabled?: boolean;
};
export type OptionsProps = {
  label: string;
  value: string;
  onValueChange: (value: string) => void;
  options: { label: string; value: string; disabled?: boolean }[];
};
export type OverlayProps = {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  title: string;
  children: React.ReactNode;
};

import React from "react";
import { Text } from "react-native";
import { useSkeuo } from "./theme";
export function SkeuoText({
  children,
  muted = false,
}: {
  children: React.ReactNode;
  muted?: boolean;
}) {
  const { colors } = useSkeuo();
  return (
    <Text
      style={{
        color: muted ? colors.muted : colors.ink,
        fontSize: 16,
        lineHeight: 24,
      }}
    >
      {children}
    </Text>
  );
}
